test('all524 previous records and independently replayed terminals, targets, full questions and labels stay fixed',async()=>{
  const {flow}=await implementation;assert.equal(frozen.flows.length,470);assert.equal(frozen.flows.reduce((sum,g)=>sum+g.nodes.length,0),3691);assert.equal(frozen.walks.length,524);
  const walks=await json('data/problem-walks.json');assert(walks.length>=525);assert.equal(digest(walks.slice(0,524)),digest(frozen.walks));
  const raw=frozen.walks.map(row=>rawWalk(frozen.flows,row.choices,row.entryGraphId));
  const observed=frozen.walks.map(row=>{const value=flow.walkFromRoot(row.choices,row.entryGraphId);assert.equal(value.consumed,row.choices.length);
    for(const id of row.expectedTechniqueIds)assert(candidates(value).includes(id));
    return {graph:value.graph.id,node:value.current.id,type:value.current.type,title:value.current.title,techniques:candidates(value),steps:value.steps,
      texts:value.steps.map(step=>{const node=flow.getNode(flow.getGraph(step.graph),step.node);return{graph:step.graph,node:step.node,question:node.title,answer:step.answer,answerLabel:flow.getNodeOptions(node).find(option=>option.id===step.answer).label,target:step.target};}),consumed:value.consumed};});
  assert.equal(digest(observed),digest(raw),'product walking must equal independent frozen raw replay including every label/target/terminal');
});

test('all470 old graphs and3691 old nodes preserve every field, old option order, answer order and exact result',async()=>{
  const {flow}=await implementation;const oldIds=frozen.flows.map(g=>g.id);assert.deepEqual(flow.graphs.filter(g=>oldIds.includes(g.id)).map(g=>g.id),oldIds);
  for(const oldGraph of frozen.flows){const graph=flow.getGraph(oldGraph.id),oldNodeIds=oldGraph.nodes.map(n=>n.id),projected={};
    assert.deepEqual(graph.nodes.filter(n=>oldNodeIds.includes(n.id)).map(n=>n.id),oldNodeIds,oldGraph.id+': node ordering');
    for(const key of Object.keys(oldGraph)){assert(Object.hasOwn(graph,key),oldGraph.id+': graph field '+key);projected[key]=structuredClone(graph[key]);}
    projected.nodes=oldGraph.nodes.map(old=>{const node=graph.nodes.find(n=>n.id===old.id),copy={};for(const key of Object.keys(old)){
      assert(Object.hasOwn(node,key),graph.id+'/'+old.id+': node field '+key);copy[key]=structuredClone(node[key]);}
      if(old.answers){const keys=Object.keys(old.answers);assert.deepEqual(Object.keys(node.answers).filter(key=>keys.includes(key)),keys,graph.id+'/'+old.id+': answer order');
        copy.answers=Object.fromEntries(keys.map(key=>[key,node.answers[key]]));
        if(old.options){assert(Array.isArray(node.options));copy.options=node.options.filter(option=>keys.includes(option.id));}
        else if(node.options!==undefined){assert.deepEqual(node.options.filter(option=>keys.includes(option.id)),options(old));}}
      assert.equal(digest(stable(copy)),digest(stable(old)),graph.id+'/'+old.id+': complete old node');return copy;});
    assert.equal(digest(stable(projected)),digest(stable(oldGraph)),graph.id+': complete old graph');}
});

